<!-- wp:kadence/column {"uniqueID":"9_8a02ca-f2","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"t-span"} -->
<div class="wp-block-kadence-column kadence-column9_8a02ca-f2 kb-section-dir-vertical t-span"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_6a1626-52","htmlTag":"span","className":"i nfi nfi-heart"} -->
<span class="kt-adv-heading9_6a1626-52 wp-block-kadence-advancedheading i nfi nfi-heart" data-kb-block="kb-adv-heading9_6a1626-52"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_272d27-69","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_272d27-69 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_272d27-69">Less brand trust</span>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->
<!-- wp:kadence/column {"uniqueID":"9_31a093-16","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"t-span"} -->
<div class="wp-block-kadence-column kadence-column9_31a093-16 kb-section-dir-vertical t-span"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_fb1c7c-02","htmlTag":"span","className":"i nfi nfi-package"} -->
<span class="kt-adv-heading9_fb1c7c-02 wp-block-kadence-advancedheading i nfi nfi-package" data-kb-block="kb-adv-heading9_fb1c7c-02"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_1863be-49","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_1863be-49 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_1863be-49">Wrong restock amounts</span>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_0f168f-6c","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_0f168f-6c wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_0f168f-6c">The last one is easy to miss. If you can\'t see how many people wanted a product while it was gone, you can\'t tell whether to reorder 20 units or 200.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/column {"uniqueID":"9_33ce14-80","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-stats rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_33ce14-80 kb-section-dir-vertical bp-stats rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_6e66b6-e4","htmlTag":"div","className":"t-div"} -->
<div class="kt-adv-heading9_6e66b6-e4 wp-block-kadence-advancedheading t-div" data-kb-block="kb-adv-heading9_6e66b6-e4"><b>1 in 3</b><span>shoppers who meet a stockout buy the item somewhere else</span></div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_c49021-76","htmlTag":"div","className":"t-div"} -->
<div class="kt-adv-heading9_c49021-76 wp-block-kadence-advancedheading t-div" data-kb-block="kb-adv-heading9_c49021-76"><b>148</b><span>people waiting on one popular size in the example above</span></div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_cd390b-1c","htmlTag":"div","className":"t-div"} -->
<div class="kt-adv-heading9_cd390b-1c wp-block-kadence-advancedheading t-div" data-kb-block="kb-adv-heading9_cd390b-1c"><b>1 click</b><span>from the restock email back to the product page</span></div>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"uniqueID":"9_f2b4d9-72","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-note rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_f2b4d9-72 kb-section-dir-vertical bp-note rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_30406b-f1","htmlTag":"span","className":"i nfi nfi-bulb"} -->
<span class="kt-adv-heading9_30406b-f1 wp-block-kadence-advancedheading i nfi nfi-bulb" data-kb-block="kb-adv-heading9_30406b-f1"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/column {"uniqueID":"9_0e9b99-23","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"t-div"} -->
<div class="wp-block-kadence-column kadence-column9_0e9b99-23 kb-section-dir-vertical t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_670dca-22","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_670dca-22 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_670dca-22"><b>Good to know</b></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_e29254-94","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_e29254-94 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_e29254-94">Shoppers who join a waitlist have already chosen the product, the size and the colour. They are some of the warmest leads your store will ever have.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_51fc5a-c5","level":2,"anchor":"how","className":"t-h2"} -->
<h2 id="how" class="kt-adv-heading9_51fc5a-c5 wp-block-kadence-advancedheading t-h2" data-kb-block="kb-adv-heading9_51fc5a-c5">How back in stock alerts work</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_ebf201-68","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_ebf201-68 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_ebf201-68">The idea is simple. When a product or variation is out of stock, the product page shows a small form instead of a dead end. The rest happens on its own:</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/column {"uniqueID":"9_6a2644-ff","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-flow rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_6a2644-ff kb-section-dir-vertical bp-flow rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_5bebfe-fb","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_5bebfe-fb wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_5bebfe-fb"><span>Product sells out</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_548db0-26","htmlTag":"span","className":"i nfi nfi-arrow"} -->
<span class="kt-adv-heading9_548db0-26 wp-block-kadence-advancedheading i nfi nfi-arrow" data-kb-block="kb-adv-heading9_548db0-26"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_40c2ba-3f","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_40c2ba-3f wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_40c2ba-3f"><span>Shopper subscribes</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_140b45-9f","htmlTag":"span","className":"i nfi nfi-arrow"} -->
<span class="kt-adv-heading9_140b45-9f wp-block-kadence-advancedheading i nfi nfi-arrow" data-kb-block="kb-adv-heading9_140b45-9f"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_811a31-6a","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_811a31-6a wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_811a31-6a"><span>You restock</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_600856-79","htmlTag":"span","className":"i nfi nfi-arrow"} -->
<span class="kt-adv-heading9_600856-79 wp-block-kadence-advancedheading i nfi nfi-arrow" data-kb-block="kb-adv-heading9_600856-79"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_057a1e-de","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_057a1e-de wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_057a1e-de"><span>Email goes out</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_16a205-e1","htmlTag":"span","className":"i nfi nfi-arrow"} -->
<span class="kt-adv-heading9_16a205-e1 wp-block-kadence-advancedheading i nfi nfi-arrow" data-kb-block="kb-adv-heading9_16a205-e1"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_2a2cc9-73","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_2a2cc9-73 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_2a2cc9-73"><span class="on">Shopper buys</span></span>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"uniqueID":"9_7ea134-3d","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-steps rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_7ea134-3d kb-section-dir-vertical bp-steps rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/column {"uniqueID":"9_11071b-10","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-step t-div"} -->
<div class="wp-block-kadence-column kadence-column9_11071b-10 kb-section-dir-vertical bp-step t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_19b1e5-11","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_19b1e5-11 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_19b1e5-11"><span class="bp-n">01</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_d6db08-58","level":3,"className":"t-h3"} -->
<h3 class="kt-adv-heading9_d6db08-58 wp-block-kadence-advancedheading t-h3" data-kb-block="kb-adv-heading9_d6db08-58">Show the form</h3>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_d82860-70","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_d82860-70 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_d82860-70">A "Notify me" form appears on every out-of-stock product and variation, styled to match your theme.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->
<!-- wp:kadence/column {"uniqueID":"9_3933cb-b9","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-step t-div"} -->
<div class="wp-block-kadence-column kadence-column9_3933cb-b9 kb-section-dir-vertical bp-step t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_b1144e-d5","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_b1144e-d5 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_b1144e-d5"><span class="bp-n">02</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_b60884-fe","level":3,"className":"t-h3"} -->
<h3 class="kt-adv-heading9_b60884-fe wp-block-kadence-advancedheading t-h3" data-kb-block="kb-adv-heading9_b60884-fe">Collect the email</h3>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_e6ea14-ac","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_e6ea14-ac wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_e6ea14-ac">The shopper enters an email. Double opt-in and reCAPTCHA keep the list real and free of spam.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->
<!-- wp:kadence/column {"uniqueID":"9_595a3d-84","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-step t-div"} -->
<div class="wp-block-kadence-column kadence-column9_595a3d-84 kb-section-dir-vertical bp-step t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_8e5b8a-03","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_8e5b8a-03 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_8e5b8a-03"><span class="bp-n">03</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_dfc9f3-b7","level":3,"className":"t-h3"} -->
<h3 class="kt-adv-heading9_dfc9f3-b7 wp-block-kadence-advancedheading t-h3" data-kb-block="kb-adv-heading9_dfc9f3-b7">Restock as usual</h3>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_559ae3-33","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_559ae3-33 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_559ae3-33">Update the stock in WooCommerce like you always do. There is nothing extra to remember.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->
<!-- wp:kadence/column {"uniqueID":"9_6df6bb-c4","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-step t-div"} -->
<div class="wp-block-kadence-column kadence-column9_6df6bb-c4 kb-section-dir-vertical bp-step t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_2fa489-68","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_2fa489-68 wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_2fa489-68"><span class="bp-n">04</span></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_efc7aa-8e","level":3,"className":"t-h3"} -->
<h3 class="kt-adv-heading9_efc7aa-8e wp-block-kadence-advancedheading t-h3" data-kb-block="kb-adv-heading9_efc7aa-8e">Alerts go out</h3>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_356492-c1","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_356492-c1 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_356492-c1">Everyone on the waitlist gets an email with a direct link back to the product, right away.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_3ca35e-1b","level":2,"anchor":"setup","className":"t-h2"} -->
<h2 id="setup" class="kt-adv-heading9_3ca35e-1b wp-block-kadence-advancedheading t-h2" data-kb-block="kb-adv-heading9_3ca35e-1b">Set it up in WooCommerce</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_5c04e5-ca","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_5c04e5-ca wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_5c04e5-ca">With Notifima, the whole setup takes a few minutes and needs no code.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/column {"uniqueID":"9_0233af-2b","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-ol t-ol"} -->
<div class="wp-block-kadence-column kadence-column9_0233af-2b kb-section-dir-vertical bp-ol t-ol"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_fa2834-74","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_fa2834-74 wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_fa2834-74"><b>Install Notifima</b> from WordPress.org and activate it.</div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_a18403-d9","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_a18403-d9 wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_a18403-d9"><b>Turn on the form</b> under Notifima → Settings. Pick which products and variations it shows on.</div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_004291-97","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_004291-97 wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_004291-97"><b>Write the email</b>. Use the product name, image and link tags so every alert is personal.</div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_903aa4-1d","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_903aa4-1d wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_903aa4-1d"><b>Add protection</b>. Switch on double opt-in and reCAPTCHA.</div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_c3633c-c3","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_c3633c-c3 wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_c3633c-c3"><b>Test it</b>. Mark a test product out of stock, subscribe, restock it, and check your inbox.</div>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"uniqueID":"9_b8c6e7-fc","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-code rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_b8c6e7-fc kb-section-dir-vertical bp-code rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_086ea0-9a","htmlTag":"div","className":"bp-code-h t-div"} -->
<div class="kt-adv-heading9_086ea0-9a wp-block-kadence-advancedheading bp-code-h t-div" data-kb-block="kb-adv-heading9_086ea0-9a"><span><i></i><i></i><i></i></span>Email subject</div>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_e930a7-05","htmlTag":"div","className":"t-pre"} -->
<div class="kt-adv-heading9_e930a7-05 wp-block-kadence-advancedheading t-pre" data-kb-block="kb-adv-heading9_e930a7-05">Good news, {first_name}! {product_name} is back in stock</div>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"uniqueID":"9_718af9-46","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-note warn rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_718af9-46 kb-section-dir-vertical bp-note warn rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_a705b8-76","htmlTag":"span","className":"i nfi nfi-alert"} -->
<span class="kt-adv-heading9_a705b8-76 wp-block-kadence-advancedheading i nfi nfi-alert" data-kb-block="kb-adv-heading9_a705b8-76"></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/column {"uniqueID":"9_bc6076-63","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"t-div"} -->
<div class="wp-block-kadence-column kadence-column9_bc6076-63 kb-section-dir-vertical t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"9_7157c1-4b","htmlTag":"span","className":"t-txt"} -->
<span class="kt-adv-heading9_7157c1-4b wp-block-kadence-advancedheading t-txt" data-kb-block="kb-adv-heading9_7157c1-4b"><b>Watch out</b></span>
<!-- /wp:kadence/advancedheading -->
<!-- wp:kadence/advancedheading {"uniqueID":"9_da77dd-81","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_da77dd-81 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_da77dd-81">Send alerts as soon as stock arrives. If you wait a day, the first shoppers to come back may find the product sold out again.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_5708c5-24","level":2,"anchor":"demand","className":"t-h2"} -->
<h2 id="demand" class="kt-adv-heading9_5708c5-24 wp-block-kadence-advancedheading t-h2" data-kb-block="kb-adv-heading9_5708c5-24">Use the waitlist to plan restocks</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"9_2ef4a1-f7","htmlTag":"p","className":"t-p"} -->
<p class="kt-adv-heading9_2ef4a1-f7 wp-block-kadence-advancedheading t-p" data-kb-block="kb-adv-heading9_2ef4a1-f7">Every subscription is a vote for a product. Notifima\'s demand tracking turns those votes into a list you can act on.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/column {"uniqueID":"9_bcd1d8-e4","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"bp-table rv t-div"} -->
<div class="wp-block-kadence-column kadence-column9_bcd1d8-e4 kb-section-dir-vertical bp-table rv t-div"><div class="kt-inside-inner-col"><!-- wp:kadence/column {"uniqueID":"9_eb0738-7e","direction":["vertical","",""],"rowGap":[0,"",""],"rowGapVariable":["custom","",""],"kbVersion":2,"className":"t-table"} -->
