<!-- wp:kadence/advancedheading {"uniqueID":"9_4f4a5f-05","htmlTag":"div","className":"t-li"} -->
<div class="kt-adv-heading9_4f4a5f-05 wp-block-kadence-advancedheading t-li" data-kb-block="kb-adv-heading9_4f4a5f-05">Double opt-in and reCAPTCHA keep your waitlist clean.</div>
